import React, { useState, useEffect } from 'react';
import { 
    Box, 
    TextField, 
    MenuItem, 
    Button, 
    useTheme,
    Typography,
    Divider,
    IconButton,
    Tooltip,
    Stack,
    alpha,
    InputAdornment
} from '@mui/material';
import { Add as AddIcon, Delete as DeleteIcon, Stars as CoinIcon, LockOutlined } from '@mui/icons-material';
import BaseModal from '../BaseModal';
import { INPUT_BG, INPUT_FONT_SIZE, INPUT_HEIGHT } from '../../theme';

const MODULE_TYPES = [
    { value: 'auth', label: 'Authentication (Login)' },
    { value: 'workout', label: 'Workouts & Fitness' },
    { value: 'social', label: 'Social & Community' },
    { value: 'profile', label: 'Profile Completion' },
    { value: 'test', label: 'Testing Activities' },
];


const FREQUENCY_LIMITS = [
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'monthly', label: 'Monthly' },
    { value: 'none', label: 'No Limit (Unlimited)' },
];

const RewardModal = ({ 
    open, 
    onClose, 
    onSubmit, 
    initialData = null, 
    loading = false 
}) => {
    const isEdit = !!initialData;
    const theme = useTheme();

    const readOnlyValueBoxSx = {
        width: '100%',
        height: INPUT_HEIGHT,
        minHeight: INPUT_HEIGHT,
        maxHeight: INPUT_HEIGHT,
        boxSizing: 'border-box',
        px: '14px',
        display: 'flex',
        alignItems: 'center',
        bgcolor: alpha(INPUT_BG, 0.55),
        backgroundImage: `linear-gradient(180deg, ${alpha('#fff', 0.03)} 0%, transparent 100%)`,
        borderRadius: '10px',
        border: `1px dashed ${alpha('#fff', 0.14)}`,
        fontSize: INPUT_FONT_SIZE,
        overflow: 'hidden',
        cursor: 'not-allowed',
        userSelect: 'none',
        opacity: 0.92,
    };

    const readOnlyFloatingLabelSx = {
        position: 'absolute',
        left: 0,
        top: 0,
        transform: 'translate(14px, -9px) scale(0.75)',
        transformOrigin: 'top left',
        zIndex: 1,
        fontSize: INPUT_FONT_SIZE,
        fontWeight: 600,
        color: alpha('#8B8D97', 0.85),
        bgcolor: theme.palette.background.paper,
        px: '6px',
        ml: '-3px',
        lineHeight: 1.25,
        pointerEvents: 'none',
        display: 'inline-flex',
        alignItems: 'center',
        gap: 0.5,
    };

    const readOnlyHelperSx = {
        mt: 0.75,
        ml: 1.5,
        fontSize: '0.7rem',
        color: alpha(theme.palette.text.secondary, 0.85),
        letterSpacing: '0.02em',
    };

    const [formData, setFormData] = useState({
        name: '',
        description: '',
        module_type: '',
        trigger_event: '',
        points_amount: 0,
        frequency_limit: 'none',
        events_per_day: 1,
        reward_type: '',
        is_active: true
    });

    useEffect(() => {
        if (open) {
            if (initialData) {
                setFormData({
                    name: initialData.name || '',
                    description: initialData.description || '',
                    module_type: initialData.module_type || '',
                    trigger_event: initialData.trigger_event || '',
                    points_amount: initialData.points_amount || 0,
                    frequency_limit: initialData.frequency_limit || 'none',
                    events_per_day: initialData.events_per_day || 1,
                    reward_type: initialData.reward_type || '',
                    is_active: initialData.is_active ?? true
                });
            } else {
                setFormData({
                    name: '',
                    description: '',
                    module_type: '',
                    trigger_event: '',
                    points_amount: 0,
                    frequency_limit: 'none',
                    events_per_day: 1,
                    reward_type: '',
                    is_active: true
                });
            }
        }
    }, [open, initialData]);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        let finalValue = type === 'checkbox' ? checked : value;
        
        // Handle numeric fields to ensure they are sent as numbers
        if (name === 'points_amount' || name === 'events_per_day') {
            finalValue = value === '' ? 0 : Number(value);
        }
        
        setFormData(prev => ({ 
            ...prev, 
            [name]: finalValue 
        }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        onSubmit(formData);
    };

    const ReadOnlyField = ({ label, value }) => (
        <Box sx={{ 
            width: '100%', 
            p: 1.5, 
            px: 2,
            bgcolor: alpha('#FFFFFF', 0.03), 
            borderRadius: '8px', 
            border: '1px solid rgba(255, 255, 255, 0.08)',
            display: 'flex',
            flexDirection: 'column',
            gap: 0.5
        }}>
            <Typography variant="caption" sx={{ color: 'text.secondary', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05rem', fontSize: '0.65rem' }}>
                {label}
            </Typography>
            <Typography variant="body2" sx={{ color: '#FFFFFF', fontWeight: 500, fontSize: '0.875rem' }}>
                {value || 'N/A'}
            </Typography>
        </Box>
    );

    const actions = (
        <Box sx={{ display: 'flex', gap: 2, width: '100%' }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    color: 'text.secondary', 
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleSubmit}
                disabled={loading || !formData.name || !formData.module_type}
                sx={{ 
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(255, 255, 255, 0.5)'
                    }
                }}
            >
                {loading ? 'Processing...' : (isEdit ? 'Save Changes' : 'Create Rule')}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={isEdit ? 'Edit Reward Rule' : 'Add New Reward Rule'}
            maxWidth="sm"
            actions={actions}
        >
            <Box 
                component="form" 
                onSubmit={handleSubmit} 
                sx={{ 
                    pt: 2,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 2,
                    width: '100%',
                }}
            >
                {isEdit ? (
                    <Box sx={{ position: 'relative', width: '100%', overflow: 'visible' }}>
                        <Box component="span" sx={readOnlyFloatingLabelSx}>
                            <LockOutlined sx={{ fontSize: 14, color: alpha('#8B8D97', 0.9) }} aria-hidden />
                            Rule Name
                            <Typography component="span" sx={{ color: 'error.main' }}>
                                *
                            </Typography>
                        </Box>
                        <Box sx={readOnlyValueBoxSx} aria-readonly="true">
                            <Typography
                                noWrap
                                title={formData.name}
                                sx={{
                                    color: alpha('#fff', 0.62),
                                    fontWeight: 500,
                                    fontSize: INPUT_FONT_SIZE,
                                    width: '100%',
                                }}
                            >
                                {formData.name}
                            </Typography>
                        </Box>
                        <Typography component="p" sx={readOnlyHelperSx}>
                            Locked  the rule name cannot be changed.
                        </Typography>
                    </Box>
                ) : (
                    <TextField
                        fullWidth
                        label="Rule Name"
                        name="name"
                        value={formData.name}
                        onChange={handleChange}
                        required
                        placeholder="e.g. Daily Login Bonus"
                    />
                )}

                {!isEdit && (
                    <>
                        <TextField
                            fullWidth
                            select
                            label="Module Type"
                            name="module_type"
                            value={formData.module_type}
                            onChange={handleChange}
                            required
                        >
                            {MODULE_TYPES.map(option => (
                                <MenuItem key={option.value} value={option.value} sx={{ fontSize: '0.875rem' }}>{option.label}</MenuItem>
                            ))}
                        </TextField>

                        <TextField
                            fullWidth
                            label="Trigger Event"
                            name="trigger_event"
                            value={formData.trigger_event}
                            onChange={handleChange}
                            required
                            placeholder="e.g. daily_login"
                        />

                        <ReadOnlyField 
                            label="Reward Type" 
                            value={formData.reward_type?.toUpperCase() || 'N/A'} 
                        />
                    </>
                )}

                <Box sx={{ width: '100%' }}>
                    <TextField
                        fullWidth
                        type="number"
                        label="Coins Amount"
                        name="points_amount"
                        value={formData.points_amount}
                        onChange={handleChange}
                        required
                        InputProps={{
                            endAdornment: <InputAdornment position="end"><CoinIcon sx={{ color: '#FFCC00', fontSize: 20 }} /></InputAdornment>,
                        }}
                    />
                    {isEdit ? (
                        <Typography component="p" sx={readOnlyHelperSx}>
                            Editable  you can change coins and description.
                        </Typography>
                    ) : null}
                </Box>

                {!isEdit && (
                    <>
                        <TextField
                            fullWidth
                            select
                            label="Frequency Limit"
                            name="frequency_limit"
                            value={formData.frequency_limit}
                            onChange={handleChange}
                            required
                        >
                            {FREQUENCY_LIMITS.map(option => (
                                <MenuItem key={option.value} value={option.value} sx={{ fontSize: '0.875rem' }}>{option.label}</MenuItem>
                            ))}
                        </TextField>

                        <TextField
                            fullWidth
                            type="number"
                            label="Max Events Per Day"
                            name="events_per_day"
                            value={formData.events_per_day}
                            onChange={handleChange}
                            required
                        />
                    </>
                )}

                <TextField
                    fullWidth
                    multiline
                    rows={3}
                    label="Rule Description"
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    required
                    placeholder="Describe when and how this reward is triggered..."
                />

                {!isEdit && (
                    <>
                        <Divider sx={{ my: 0.5, borderColor: 'rgba(255,255,255,0.06)' }} />
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', p: 1, px: 1.5, bgcolor: alpha('#FFFFFF', 0.02), borderRadius: '8px' }}>
                            <Typography variant="body2" sx={{ color: 'text.secondary', fontWeight: 600 }}>
                                Rule Status (Active/Inactive)
                            </Typography>
                            <Box 
                                component="input"
                                type="checkbox"
                                name="is_active"
                                checked={formData.is_active}
                                onChange={handleChange}
                                sx={{ 
                                    width: 40, 
                                    height: 20, 
                                    appearance: 'none',
                                    bgcolor: formData.is_active ? '#4CC66E' : '#333333',
                                    borderRadius: '20px',
                                    position: 'relative',
                                    cursor: 'pointer',
                                    '&::before': {
                                        content: '""',
                                        position: 'absolute',
                                        width: 16,
                                        height: 16,
                                        bgcolor: '#FFFFFF',
                                        borderRadius: '50%',
                                        top: 2,
                                        left: formData.is_active ? 22 : 2,
                                        transition: '0.3s'
                                    }
                                }}
                            />
                        </Box>
                    </>
                )}
            </Box>
        </BaseModal>
    );
};

export default RewardModal;
