import React, { useState, memo } from 'react';
import {
    Box,
    Menu,
    MenuItem,
    Chip,
    Typography,
    alpha,
    useTheme,
    CircularProgress
} from '@mui/material';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';

// Master status configurations for all possible values
const MASTER_STATUS_CONFIG = {
    blocked: { label: 'Blocked', color: '#FF5050' },
    unblocked: { label: 'Unblocked', color: '#4CC66E' },
    default: { label: 'Unknown', color: '#8B8D97' }
};

const defaultStatuses = [
    { label: 'Blocked', value: 'blocked', color: '#FF5050' },
    { label: 'Active', value: 'unblocked', color: '#4CC66E' },
];

const StatusDropdown = ({
    status,
    options = defaultStatuses,
    onStatusChange,
    isLoading = false,
    disabled = false
}) => {
    const theme = useTheme();
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);

    const safeStatus = status?.toLowerCase() || 'pending';
    const currentStatusConfig = options.find(opt => opt.value === safeStatus) || 
                               MASTER_STATUS_CONFIG[safeStatus] || 
                               MASTER_STATUS_CONFIG.default;

    const currentStatusLabel = currentStatusConfig.label || status || 'Pending';
    const activeColor = currentStatusConfig.color || '#8B8D97';

    const handleClick = (event) => {
        event.stopPropagation();
        if (!disabled && !isLoading) {
            setAnchorEl(event.currentTarget);
        }
    };

    const handleClose = () => {
        setAnchorEl(null);
    };

    const handleSelect = (value) => {
        if (value !== status && onStatusChange) {
            onStatusChange(value);
        }
        handleClose();
    };

    return (
        <Box onClick={(e) => e.stopPropagation()}>
            <Chip
                label={
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        {isLoading && <CircularProgress size={12} sx={{ color: activeColor }} thickness={6} />}
                        <Typography 
                            variant="caption" 
                            sx={{ 
                                fontWeight: 700, 
                                lineHeight: 1,
                                fontFamily: "'Montserrat', sans-serif",
                                fontSize: '0.7rem',
                                textTransform: 'uppercase'
                            }}
                        >
                            {currentStatusLabel}
                        </Typography>
                        {!isLoading && <KeyboardArrowDownIcon sx={{ fontSize: '0.8rem', opacity: 0.8 }} />}
                    </Box>
                }
                onClick={handleClick}
                sx={{
                    cursor: disabled || isLoading ? 'default' : 'pointer',
                    height: '24px',
                    px: 0.5,
                    borderRadius: '6px',
                    backgroundColor: alpha(activeColor, 0.12),
                    color: activeColor,
                    border: '1px solid',
                    borderColor: alpha(activeColor, 0.3),
                    '&:hover': {
                        backgroundColor: !disabled && !isLoading ? alpha(activeColor, 0.2) : alpha(activeColor, 0.12),
                        borderColor: alpha(activeColor, 0.5),
                    },
                    transition: 'all 0.2s ease',
                    fontFamily: "'Montserrat', sans-serif",
                }}
            />

            <Menu
                anchorEl={anchorEl}
                open={open}
                onClose={handleClose}
                onClick={(e) => e.stopPropagation()}
                PaperProps={{
                    sx: {
                        mt: 0.5,
                        minWidth: 120,
                        backgroundColor: '#001e08ff',
                        borderRadius: '8px',
                        border: '1px solid #333333',
                        boxShadow: '0 4px 20px rgba(0,0,0,0.5)',
                        '& .MuiMenuItem-root': {
                            fontSize: '0.75rem',
                            fontWeight: 600,
                            fontFamily: "'Montserrat', sans-serif",
                            borderRadius: '4px',
                            mx: 0.5,
                            my: 0.2,
                            py: 0.8,
                            color: '#FFFFFF',
                            transition: 'all 0.2s ease',
                            '&:hover': {
                                backgroundColor: 'rgba(255, 255, 255, 0.05)',
                                color: '#4CC66E',
                            },
                            '&.Mui-selected': {
                                backgroundColor: 'rgba(76, 198, 110, 0.15)',
                                color: '#4CC66E',
                                '&:hover': {
                                    backgroundColor: 'rgba(76, 198, 110, 0.25)',
                                }
                            }
                        }
                    }
                }}
            >
                {options.map((option) => (
                    <MenuItem
                        key={option.value}
                        onClick={() => handleSelect(option.value)}
                        selected={option.value === safeStatus}
                    >
                        <Box sx={{
                            width: 6,
                            height: 6,
                            borderRadius: '50%',
                            mr: 1.5,
                            backgroundColor: option.color || '#8B8D97'
                        }} />
                        {option.label}
                    </MenuItem>
                ))}
            </Menu>
        </Box>
    );
};

export default memo(StatusDropdown);
