import React, { useState, useMemo, useEffect } from "react";
import {
  Box,
  Typography,
  IconButton,
  Tooltip,
  alpha,
  useTheme,
  Divider,
  Stack,
} from "@mui/material";
import {
  Visibility as ViewIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Stars as CoinIcon,
  MilitaryTech as LevelIcon,
  List as ListIcon,
  HelpOutline as TipsIcon,
  ErrorOutline as PitfallIcon,
  AssignmentTurnedIn as TaskIcon,
  Stars as RarityIcon,
} from "@mui/icons-material";
import DataTable from "../../../components/DataTable";
import DisplayChip from "../../../components/DisplayChip";
import DetailsModal from "../../../components/DetailsModal";
import ConfirmationModal from "../../../components/ConfirmationModal";
import RewardModal from "../../../components/page_components/RewardModal";
import { toast } from "react-hot-toast";
import { useSelector } from "react-redux";
import { mapRewardRuleExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import StatusDropdown from "../../../components/StatusDropdown";
import { useCallback } from "react";
import dayjs from "dayjs";

const MODULE_COLORS = {
  auth: "#BF5AF2",
  workout: "#5AC8FA",
  test: "#8B8D97",
  social: "#FF9F0A",
  profile: "#4CC66E",
};






const BASE_URL = process.env.REACT_APP_API_BASE_URL || 'https://api.fitness-savage.mtechub.com/api/v1';

const Rewards = () => {
  const theme = useTheme();
  const [rewards, setRewards] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");
  const [isExporting, setIsExporting] = useState(false);

  const [openViewModal, setOpenViewModal] = useState(false);
  const [openAddEditModal, setOpenAddEditModal] = useState(false);
  const [openDeleteModal, setOpenDeleteModal] = useState(false);
  const [selectedReward, setSelectedReward] = useState(null);
  const [rewardToEdit, setRewardToEdit] = useState(null);
  const [rewardToDelete, setRewardToDelete] = useState(null);
  const [isSaving, setIsSaving] = useState(false);
  const [updatingStatusId, setUpdatingStatusId] = useState(null);

  const REWARD_STATUS_OPTIONS = [
    { label: 'Active', value: 'active', color: '#4CC66E' },
    { label: 'Inactive', value: 'inactive', color: '#FF5050' },
  ];

  const token = useSelector((state) => state.auth.token);

  const fetchRewards = useCallback(async () => {
    if (!token) return;
    setIsLoading(true);
    try {
      const queryParams = new URLSearchParams({
        page: page + 1,
        limit: rowsPerPage,
        sort_by: orderBy,
        sort_order: order,
        q: searchTerm,
      });

      const response = await fetch(`${BASE_URL}/rewards/rules?${queryParams.toString()}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        setRewards(result.data.rules || []);
        setTotalCount(result.data.pagination?.total || 0);
      } else {
        toast.error(result.message || "Failed to fetch reward rules");
      }
    } catch (error) {
      console.error("Fetch error:", error);
      toast.error("Error connecting to server");
    } finally {
      setIsLoading(false);
    }
  }, [token, page, rowsPerPage, orderBy, order, searchTerm]);

  useEffect(() => {
    fetchRewards();
  }, [fetchRewards]);

  const handleExport = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting reward rules as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const queryParams = new URLSearchParams({
        sort_by: orderBy,
        sort_order: order,
        q: searchTerm,
        not_pagination: "true",
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      });

      const response = await fetch(`${BASE_URL}/rewards/rules?${queryParams.toString()}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const result = await response.json();
      if (!response.ok || result.error) {
        throw new Error(result.message || "Failed to fetch reward rules for export");
      }

      const items = extractExportList(result, 'rules');
      const filename = `Reward_Rules_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapRewardRuleExport,
        format,
        filename,
        sheetName: 'Rewards',
        entityName: 'reward rules',
        toastId,
      });
    } catch (error) {
      console.error("Export error:", error);
      toast.error(error.message || "Connection error during export", { id: toastId });
    } finally {
      setIsExporting(false);
    }
  }, [token, orderBy, order, searchTerm]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const handleViewDetails = (reward) => {
    setSelectedReward(reward);
    setOpenViewModal(true);
  };

  const handleEditClick = (reward) => {
    setRewardToEdit(reward);
    setOpenAddEditModal(true);
  };

  const handleAddClick = () => {
    setRewardToEdit(null);
    setOpenAddEditModal(true);
  };

  const handleDeleteClick = (reward) => {
    setRewardToDelete(reward);
    setOpenDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!token || !rewardToDelete) return;
    const toastId = toast.loading("Deleting reward rule...");
    try {
      const response = await fetch(`${BASE_URL}/rewards/rules/${rewardToDelete.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success("Rule deleted successfully!", { id: toastId });
        setOpenDeleteModal(false);
        setRewardToDelete(null);
        fetchRewards();
      } else {
        toast.error(result.message || "Delete failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Internal server error", { id: toastId });
    }
  };


  const handleSaveReward = async (formData) => {
    if (!token) return;
    setIsSaving(true);
    const toastId = toast.loading(`${rewardToEdit ? 'Updating' : 'Creating'} rule...`);
    try {
      const url = rewardToEdit 
        ? `${BASE_URL}/rewards/rules/${rewardToEdit.id}`
        : `${BASE_URL}/rewards/rules`;

      const body = rewardToEdit ? { ...formData, name: rewardToEdit.name } : formData;

      const response = await fetch(url, {
        method: rewardToEdit ? "PUT" : "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success(`Rule ${rewardToEdit ? 'Updated' : 'Created'} Successfully!`, { id: toastId });
        setOpenAddEditModal(false);
        setRewardToEdit(null);
        fetchRewards();
      } else {
        toast.error(result.message || "Save failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Internal server error", { id: toastId });
    } finally {
      setIsSaving(false);
    }
  };

  const handleStatusUpdate = async (id, newStatus) => {
    if (!token) return;
    setUpdatingStatusId(id);
    const isActive = newStatus === 'active';
    
    const updatePromise = fetch(`${BASE_URL}/rewards/rules/${id}`, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ is_active: isActive }),
    }).then(async (res) => {
      const result = await res.json();
      if (!res.ok || result.error) throw new Error(result.message || 'Status update failed');
      fetchRewards();
      return result;
    });

    toast.promise(updatePromise, {
      loading: 'Updating status...',
      success: 'Status updated successfully!',
      error: (err) => err.message
    });

    try {
      await updatePromise;
    } catch (error) {
      console.error('Status update error:', error);
    } finally {
      setUpdatingStatusId(null);
    }
  };

  const columns = [
    {
      id: "name",
      label: "Rule Name",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <Box>
            <Typography sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.875rem" }}>
              {row.name}
            </Typography>
            <Typography variant="caption" sx={{ color: "#8B8D97", display: 'block', maxWidth: 200, noWrap: true, textOverflow: 'ellipsis', overflow: 'hidden' }}>
              {row.description}
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
      id: "module_type",
      label: "Module",
      sortable: true,
      render: (row) => (
        <DisplayChip
          label={row.module_type?.toUpperCase() || "N/A"}
          size="small"
          sx={{
            bgcolor: alpha(MODULE_COLORS[row.module_type] || "#8B8D97", 0.15),
            color: MODULE_COLORS[row.module_type] || "#8B8D97",
            fontWeight: 800,
            fontSize: "0.65rem",
            borderRadius: "6px",
            border: `1px solid ${alpha(MODULE_COLORS[row.module_type] || "#8B8D97", 0.3)}`,
          }}
        />
      ),
    },
    {
      id: "trigger_event",
      label: "Trigger Event",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.8rem", textTransform: 'capitalize' }}>
          {row.trigger_event?.replace(/_/g, ' ')}
        </Typography>
      ),
    },
    {
      id: "points_amount",
      label: "Reward",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
          <CoinIcon sx={{ fontSize: 16, color: "#FFCC00" }} />
          <Typography sx={{ color: "#FFCC00", fontWeight: 800, fontSize: "0.9rem" }}>
            {row.points_amount} <span style={{ fontSize: '0.7rem', color: '#8B8D97' }}>coins</span>
          </Typography>
        </Box>
      ),
    },
    {
      id: "is_active",
      label: "Status",
      sortable: true,
      render: (row) => (
        <StatusDropdown
          status={row.is_active ? 'active' : 'inactive'}
          options={REWARD_STATUS_OPTIONS}
          onStatusChange={(newVal) => handleStatusUpdate(row.id, newVal)}
          isLoading={updatingStatusId === row.id}
        />
      ),
    },
    {
      id: "actions",
      label: "Actions",
      render: (row) => (
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="View Details">
            <IconButton
              size="small"
              onClick={() => handleViewDetails(row)}
              sx={{ color: "#9F6EDA", bgcolor: alpha("#9F6EDA", 0.1), "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) } }}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Edit">
            <IconButton
              size="small"
              onClick={() => handleEditClick(row)}
              sx={{ color: "#9F6EDA", bgcolor: alpha("#9F6EDA", 0.1), "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) } }}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          {/* <Tooltip title="Delete">
            <IconButton
              size="small"
              onClick={() => handleDeleteClick(row)}
              sx={{ color: "#FF5050", bgcolor: alpha("#FF5050", 0.1), "&:hover": { bgcolor: alpha("#FF5050", 0.2) } }}
            >
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Tooltip> */}
        </Box>
      ),
    },
  ];

  const rewardDetailsData = useMemo(() => {
    if (!selectedReward) return [];
    return [
      { label: "Rule Name", value: selectedReward.name },
      { label: "Module Type", value: selectedReward.module_type?.toUpperCase(), color: MODULE_COLORS[selectedReward.module_type] },
      { label: "Trigger Event", value: selectedReward.trigger_event?.replace(/_/g, ' ') },
      {
        label: "Coins Allowed",
        value: `${selectedReward.points_amount} Coins`,
        color: "#FFCC00",
      },
      {
        label: "Frequency Limit",
        value: selectedReward.frequency_limit || "None (Unlimited)",
      },
      {
        label: "Daily Limit",
        value: `${selectedReward.events_per_day} events per day`,
      },
      {
        label: "Active Status",
        value: selectedReward.is_active ? "ACTIVE" : "INACTIVE",
        color: selectedReward.is_active ? "#4CC66E" : "#FF5050",
      },
      {
        label: "Rule Description",
        value: selectedReward.description || "No description provided",
        vertical: true,
      },
      {
        label: "Date Created",
        value: selectedReward.created_at
          ? new Date(selectedReward.created_at).toLocaleString()
          : "N/A",
      },
    ];
  }, [selectedReward]);

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="Manage Reward Rules"
        columns={columns}
        data={rewards}
        isLoading={isLoading}
        // onAddClick={handleAddClick}
        // addLabel="Add New Rule"
        onExport={handleExport}
        isExporting={isExporting}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No reward rules found"
         />

      {selectedReward && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Reward Rule Details"
          data={rewardDetailsData}
          maxWidth="sm"
        />
      )}

      <RewardModal
        open={openAddEditModal}
        onClose={() => setOpenAddEditModal(false)}
        onSubmit={handleSaveReward}
        initialData={rewardToEdit}
        loading={isSaving}
      />

      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Reward Rule?"
        message="Are you sure you want to delete this reward rule? This will stop future rewards for this event triggering but won't affect previously earned coins."
        confirmText="Delete"
        confirmColor="error"
      />

    </Box>
  );
};

export default Rewards;
